def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if shift > n:
        return s[::-1]
    if shift == n:
        return s
    shift = shift % n
    if shift == 0:
        return s
    # shift left by shift positions
    return s[shift:] + s[:shift]

